/**
 * Regenerate the shared org catalog barrel (`generated/catalog.ts`): imports
 * every app's, element's, and table's own per-entity `generated/catalog.ts`
 * (written by `writeAppCatalog`/`writeAppCatalogFromAuthoring`) and exposes
 * apps/elements flat plus tables under both `catalog.tables` and `org.tables`
 * (printers emit `org.tables.*`; automations historically use `catalog.tables.*`),
 * alongside org AI providers/cloud links. `import catalog from "@catalog"` gives
 * `catalog.testingAles`, `catalog.tables.orders`,
 * `catalog.aiProviders.anthropic.models.claudeOpus_4_6`, etc.
 *
 * Elements and apps share the exact same per-entity catalog shape — an
 * element just lives under `elements/<handle>/` instead of `apps/<handle>/`.
 * There's nothing element-specific left in this file; it only needs to know
 * where to look.
 *
 * Called by every import command that touches org state (importApp,
 * importCloudLinks, importConnectors) so the catalog is always in sync.
 */
import { existsSync } from "node:fs";
import { readdir } from "node:fs/promises";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { AI_PROVIDER_TYPE_BY_RESOURCE_TYPE, ORG_IDENTITY_BAGS, orgRootOwnFileBags } from "../graph/index.js";
import { sanitizeName, tfLabelToTsLabel, tsLabelToTfLabel } from "../engine/tf/index.js";
import { sdkPackageSpecifier } from "../internal/sdk-package.js";
import { OrgExtractError } from "../engine/pull/org.js";
// ---------------------------------------------------------------------------
// Public entry points
// ---------------------------------------------------------------------------
export async function writeOrgCatalogFromExtract(root, extract) {
    const genDir = join(root, "generated");
    const catalogPath = join(genDir, "catalog.ts");
    const orgPath = join(root, "org.ts");
    const { appHandles, elementHandles, tableHandles } = await discoverOrgRootHandles(root);
    await mkdir(genDir, { recursive: true });
    await writeFile(orgPath, renderOrgTs(extract), "utf8");
    await writeFile(catalogPath, renderBarrel(appHandles, elementHandles, tableHandles), "utf8");
    return { catalogPath, orgPath };
}
/**
 * Rewrite generated/catalog.ts ALONE from the current file tree — org.ts is
 * untouched (it belongs to `pull org`). Called after a pull writes new
 * authoring (apps/agents) so `@catalog` resolves the fresh entries.
 */
export async function writeCatalogBarrel(root) {
    const genDir = join(root, "generated");
    const catalogPath = join(genDir, "catalog.ts");
    const { appHandles, elementHandles, tableHandles } = await discoverOrgRootHandles(root);
    await mkdir(genDir, { recursive: true });
    await writeFile(catalogPath, renderBarrel(appHandles, elementHandles, tableHandles), "utf8");
    return catalogPath;
}
/** Render generated/org.ts from the stream extract — bag/factory from CatalogFacet. */
function renderOrgTs(extract) {
    const bags = ORG_IDENTITY_BAGS.flatMap((m) => {
        if (!m.data.participates || m.data.orgBag === undefined || !m.catalog.participates)
            return [];
        const bag = m.data.orgBag;
        const factory = m.catalog.factoryName ?? `${m.catalog.refKind}Ref`;
        const entries = extract[bag];
        if (entries.length === 0)
            return [];
        return [{ bag, factory, entries, order: m.catalog.renderOrder }];
    }).sort((a, b) => a.order - b.order || a.bag.localeCompare(b.bag));
    // connector and the 10 ai-provider-* kinds are all `catalog: NO_CATALOG` —
    // they never appear in `bags` above. Models nest on their provider instead
    // (`aiProviders.<provider>.models.<model>`), rendered specially here.
    const aiProvidersLines = renderAiProvidersBag(extract);
    const supportedFunctionsByCloudLink = new Map();
    const supportedProceduresByCloudLink = new Map();
    for (const fn of extract.storedFunctions ?? []) {
        const mapped = supportedStoredFunction(fn);
        if (mapped === undefined)
            continue;
        const target = fn.functionType === "PROCEDURE"
            ? supportedProceduresByCloudLink
            : supportedFunctionsByCloudLink;
        const entries = target.get(fn.cloudLinkName) ?? [];
        entries.push({ fn, mapped });
        target.set(fn.cloudLinkName, entries);
    }
    const factories = new Set(["orgCatalog", ...bags.map((b) => b.factory)]);
    if (aiProvidersLines.length > 0) {
        factories.add("aiProvider");
        factories.add("connectorRef");
    }
    if (supportedFunctionsByCloudLink.size > 0)
        factories.add("storedFunctionRef");
    if (supportedProceduresByCloudLink.size > 0)
        factories.add("procedureRef");
    const lines = [
        "// Org reference identities from `elementum pull org --data-only` — refresh by re-running it.",
        "// Each key IS the identity's terraform label in camelCase: tfLabel = tsLabelToTfLabel(key)",
        "// (the lossless bijection in src/tf/labels.ts — the stable naming contract).",
        `import { ${[...factories].sort().join(", ")} } from "${sdkPackageSpecifier("catalog")}";`,
        "",
        "export const org = orgCatalog({",
        ...aiProvidersLines,
    ];
    for (const { bag, factory, entries } of bags) {
        lines.push(`  ${bag}: {`);
        for (const e of entries) {
            if (bag !== "cloudLinks") {
                lines.push(`    ${e.tsLabel}: ${factory}({ name: ${q(e.name)} }),`);
                continue;
            }
            const functions = supportedFunctionsByCloudLink.get(e.name) ?? [];
            const procedures = supportedProceduresByCloudLink.get(e.name) ?? [];
            if (functions.length === 0 && procedures.length === 0) {
                lines.push(`    ${e.tsLabel}: ${factory}({ name: ${q(e.name)} }),`);
                continue;
            }
            lines.push(`    ${e.tsLabel}: ${factory}({ name: ${q(e.name)},`);
            if (functions.length > 0) {
                lines.push("      storedFunctions: {");
                const used = new Set();
                for (const { fn, mapped } of functions) {
                    const key = uniqueCatalogKey(tfLabelToTsLabel(sanitizeName(fn.name)), used);
                    lines.push(`        ${key}: storedFunctionRef({ name: ${q(fn.name)}, parameters: ${JSON.stringify(mapped.parameters)}, result: ${q(mapped.result)} }),`);
                }
                lines.push("      },");
            }
            if (procedures.length > 0) {
                lines.push("      procedures: {");
                const used = new Set();
                for (const { fn, mapped } of procedures) {
                    const key = uniqueCatalogKey(tfLabelToTsLabel(sanitizeName(fn.name)), used);
                    lines.push(`        ${key}: procedureRef({ name: ${q(fn.name)}, database: ${q(fn.databaseName)}, schema: ${q(fn.schemaName)}, parameters: ${JSON.stringify(fn.parameterTypes)}, result: ${q(mapped.result)} }),`);
                }
                lines.push("      },");
            }
            lines.push("    }),");
        }
        lines.push("  },");
    }
    lines.push("});", "");
    return lines.join("\n");
}
const STORED_FUNCTION_TYPE = {
    AUTO_INCREMENT: "number",
    LONG: "number",
    BOOLEAN: "bool",
    DATE: "date",
    DATETIME: "datetime",
    DECIMAL: "decimal",
    HANDLE: "handle",
    JSON: "json",
    TEXT: "text",
    UUID: "text",
    BINARY: undefined,
};
function supportedStoredFunction(fn) {
    const knownKind = fn.functionType === "USER_DEFINED_FUNCTION" || fn.functionType === "PROCEDURE";
    const problem = !knownKind ? `type ${fn.functionType}`
        : !fn.configured ? "not configured"
            : fn.returnType === "TABLE" ? "table result"
                : fn.functionType === "PROCEDURE" && fn.parameterTypes.includes("AUTO_INCREMENT") ? "unsupported procedure argument AUTO_INCREMENT"
                    : STORED_FUNCTION_TYPE[fn.returnType] === undefined ? `unsupported result ${fn.returnType}`
                        : fn.parameterTypes.some((type) => STORED_FUNCTION_TYPE[type] === undefined) ? `unsupported argument in ${fn.parameterTypes.join(", ")}`
                            : undefined;
    if (problem !== undefined) {
        console.error(`[elementum] skipping stored function ${fn.name}: ${problem}`);
        return undefined;
    }
    return {
        parameters: fn.parameterTypes.map((type) => STORED_FUNCTION_TYPE[type]),
        result: STORED_FUNCTION_TYPE[fn.returnType],
    };
}
/**
 * Connectors nest one level under their provider — model names alone collide
 * across providers, so `aiProviders.<provider>.models.<model>` disambiguates
 * instead of a flat `connectors.<model>`. Provider/model keys are
 * independently derived from `name`/`model_name` (never split out of the
 * connector's combined tfLabel) and cross-checked against the recorded
 * tfLabel — a mismatch means ei's label construction drifted from this
 * derivation. Connectors without a resolved provider are reported by
 * `extractOrg` and skipped here because they cannot be represented safely in
 * the nested public catalog.
 */
function renderAiProvidersBag(extract) {
    if (extract.aiProviders.length === 0)
        return [];
    const providerByRef = new Map();
    for (const provider of extract.aiProviders) {
        providerByRef.set(`${provider.resourceType}.${provider.tfLabel}`, provider);
    }
    const modelsByProviderKey = new Map();
    for (const connector of extract.connectors) {
        if (connector.providerRef === undefined) {
            continue;
        }
        const providerRefKey = `${connector.providerRef.resourceType}.${connector.providerRef.tfLabel}`;
        const provider = providerByRef.get(providerRefKey);
        if (provider === undefined) {
            continue;
        }
        const providerKey = tfLabelToTsLabel(sanitizeName(provider.name));
        const modelKey = tfLabelToTsLabel(sanitizeName(connector.name));
        const rebuilt = `${tsLabelToTfLabel(providerKey)}_${tsLabelToTfLabel(modelKey)}`;
        if (rebuilt !== connector.tfLabel) {
            throw new OrgExtractError(`connector "${connector.name}" / provider "${provider.name}": derived label "${rebuilt}" doesn't match ei's recorded label "${connector.tfLabel}" — label derivation drifted`);
        }
        const models = modelsByProviderKey.get(providerKey) ?? [];
        if (models.some((m) => m.modelKey === modelKey)) {
            throw new OrgExtractError(`provider "${provider.name}": two connectors both derive the model key "${modelKey}"`);
        }
        models.push({ modelKey, connector });
        modelsByProviderKey.set(providerKey, models);
    }
    const providers = extract.aiProviders
        .map((provider) => ({ provider, providerKey: tfLabelToTsLabel(sanitizeName(provider.name)) }))
        .sort((a, b) => a.providerKey.localeCompare(b.providerKey));
    const lines = ["  aiProviders: {"];
    for (const { provider, providerKey } of providers) {
        const type = AI_PROVIDER_TYPE_BY_RESOURCE_TYPE.get(provider.resourceType);
        if (type === undefined) {
            throw new OrgExtractError(`provider "${provider.name}": unrecognized resource type "${provider.resourceType}"`);
        }
        const models = (modelsByProviderKey.get(providerKey) ?? []).sort((a, b) => a.modelKey.localeCompare(b.modelKey));
        if (models.length === 0) {
            lines.push(`    ${providerKey}: aiProvider({ name: ${q(provider.name)}, type: ${q(type)} }),`);
            continue;
        }
        lines.push(`    ${providerKey}: aiProvider({ name: ${q(provider.name)}, type: ${q(type)}, models: {`);
        for (const { modelKey, connector } of models) {
            lines.push(`      ${modelKey}: connectorRef({ name: ${q(connector.name)} }),`);
        }
        lines.push("    } }),");
    }
    lines.push("  },");
    return lines;
}
/**
 * Render generated/catalog.ts as a pure barrel over org.ts + disk-scanned
 * catalogs — every app/element/table entry is a lazy `get` accessor (a
 * `require(...)` inside the getter body, type-asserted via `typeof
 * import(...)` so `Ref`/autocomplete stay fully typed) rather than a
 * static top-level import.
 *
 * This is NOT cosmetic: a relation field authored on a root app/element's
 * own file can reference ANOTHER sibling via `catalog.<ref>` (see
 * `entities/field/to-tf.ts`'s `workspaceAspects` sibling resolution) — the
 * first real case of a root file importing `@catalog` itself. But the
 * barrel unconditionally aggregates EVERY app/element, including the
 * importing file's own entry, so a static import here would statically
 * import that file's own per-entity catalog, which itself statically
 * imports the file currently mid-evaluation — a genuine circular require
 * (confirmed live: CJS semantics hand back a partial, `export
 * default`-less module, and `.ref()` on it throws). A lazy getter defers
 * that whole chain until the property is actually READ, by which point
 * the importing file's own module evaluation has moved past the point of
 * needing it (or, for a property this file never touches at all — e.g.
 * `knowledge.ts` only ever reads `catalog.tickets`, never
 * `catalog.knowledge` — the getter for its OWN entry is simply never
 * invoked, so its self-referential chain never runs).
 */
function renderBarrel(appHandles, elementHandles, tableHandles) {
    const elementKeys = computeElementKeys(appHandles, elementHandles);
    const hasLazyEntries = appHandles.length > 0 || elementHandles.length > 0 || tableHandles.length > 0;
    const lines = [
        // Alias so we can re-export `org` with the pulled `tables` bag attached —
        // table printers emit `org.tables.*` while automations historically use
        // `catalog.tables.*`. Both must resolve the same lazy getters.
        'import { org as orgIdentities } from "../org.js";',
        'import { usersCatalog } from "@elementumai/edk/catalog";',
        "",
    ];
    if (hasLazyEntries) {
        // A synchronous require for the lazy getters below. Native ESM uses
        // createRequire; the Bun binary's jiti fallback supplies its own require,
        // which must win there so nested generated catalogs stay inside jiti's
        // resolver. An import would eagerly pull every per-entity catalog into
        // this module's evaluation and reintroduce the self-reference cycle.
        lines.push('import { createRequire } from "node:module";', "");
        lines.push('const catalogRequire = (globalThis as { Bun?: unknown }).Bun !== undefined && typeof require === "function"', "  ? require", "  : createRequire(import.meta.url);", "");
    }
    if (tableHandles.length > 0) {
        lines.push("const tables = {");
        for (const h of tableHandles)
            lines.push(...lazyAspectGetter(safeKey(h), `../tables/${h}/generated/catalog.js`, "default", "  "));
        lines.push("};", "");
    }
    lines.push("const catalog = {");
    for (const h of appHandles)
        lines.push(...lazyAspectGetter(h, `../apps/${h}/generated/catalog.js`, h));
    for (const h of elementHandles) {
        lines.push(...lazyAspectGetter(elementKeys.get(h), `../elements/${h}/generated/catalog.js`, h));
    }
    lines.push("  users: usersCatalog,");
    lines.push("  aiProviders: orgIdentities.aiProviders,");
    lines.push("  cloudLinks: orgIdentities.cloudLinks,");
    lines.push("  categories: orgIdentities.categories,");
    lines.push("  groups: orgIdentities.groups,");
    lines.push("  phoneProviders: orgIdentities.phoneProviders,");
    if (tableHandles.length > 0)
        lines.push("  tables,");
    lines.push("};");
    if (tableHandles.length > 0) {
        lines.push("", "const org = { ...orgIdentities, tables };", "export { org };");
    }
    else {
        lines.push("", "export { orgIdentities as org };");
    }
    lines.push("export type Ref = typeof catalog;", "export default catalog;", "");
    return lines.join("\n");
}
/**
 * One lazy `get <key>() { ... }` accessor: `require`s `importPath` only when
 * read, type-asserted as `typeof import(importPath)` so the property's
 * static type is exactly what a real `import` would have given it.
 */
function lazyAspectGetter(key, importPath, exportName, indent = "  ") {
    const quoted = JSON.stringify(importPath);
    return [
        `${indent}get ${key}() { return (catalogRequire(${quoted}) as typeof import(${quoted})).${exportName}; },`,
    ];
}
/** An app and an element MAY share a handle — expose the element under a disambiguated key, warning once. */
function computeElementKeys(appHandles, elementHandles) {
    const used = new Set(appHandles);
    const elementKeys = new Map();
    for (const h of elementHandles) {
        if (!used.has(h)) {
            elementKeys.set(h, h);
            used.add(h);
            continue;
        }
        let i = 2;
        let candidate = `${h}${i}`;
        while (used.has(candidate)) {
            i++;
            candidate = `${h}${i}`;
        }
        elementKeys.set(h, candidate);
        used.add(candidate);
        console.error(`[elementum] warning: "${h}" names both an app and an element — the element is exposed as catalog.${candidate} (the app keeps catalog.${h}) to avoid a collision.`);
    }
    return elementKeys;
}
// ---------------------------------------------------------------------------
// App / element / table handle discovery (dirs from orgRootOwnFileBags)
// ---------------------------------------------------------------------------
async function discoverHandles(root, subdir) {
    const dir = join(root, subdir);
    const handles = [];
    try {
        const entries = await readdir(dir, { withFileTypes: true });
        for (const e of entries) {
            if (!e.isDirectory())
                continue;
            if (existsSync(join(dir, e.name, "generated", "catalog.ts"))) {
                handles.push(e.name);
            }
        }
    }
    catch { /* subdir doesn't exist yet — no handles */ }
    return handles.sort();
}
/**
 * Scan org-root own-file bags from the graph. Apps/elements stay flat on the
 * barrel; `tables` nests under `catalog.tables` (historical shape).
 */
async function discoverOrgRootHandles(root) {
    const bags = new Set(orgRootOwnFileBags());
    const appHandles = bags.has("apps") ? await discoverHandles(root, "apps") : [];
    const elementHandles = bags.has("elements") ? await discoverHandles(root, "elements") : [];
    const tableHandles = bags.has("tables") ? await discoverHandles(root, "tables") : [];
    return { appHandles, elementHandles, tableHandles };
}
// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------
function q(s) {
    return JSON.stringify(s);
}
/**
 * Disambiguate a catalog bag key against sibling keys already used in the
 * same bag, appending numeric suffixes (`base`, `base2`, `base3`, …) — the
 * same dedupe rule `withUniqueKeys` (`pull/util.ts`) applies elsewhere in the
 * codebase. Needed because overloaded Snowflake stored functions/procedures
 * (same name, distinct parameter signature) derive the same `sanitizeName`
 * base; each still carries its own exact `name`/`database`/`schema`/
 * `parameters` in the emitted ref, so only the bag KEY needs disambiguating.
 */
function uniqueCatalogKey(base, used) {
    let key = base;
    let i = 2;
    while (used.has(key))
        key = `${base}${i++}`;
    used.add(key);
    return key;
}
const RESERVED_IDENT = new Set([
    "break", "case", "catch", "class", "const", "continue", "debugger", "default",
    "delete", "do", "else", "export", "extends", "false", "finally", "for",
    "function", "if", "import", "in", "instanceof", "new", "null", "return",
    "super", "switch", "this", "throw", "true", "try", "typeof", "var", "void",
    "while", "with", "let", "static", "yield", "enum",
]);
function safeKey(name) {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) && !RESERVED_IDENT.has(name)
        ? name
        : q(name);
}
